  "title": "Open Design Landing Deck",
  "title_i18n": {
    "zh-CN": "Open Design 着陆演示套件",
    "zh-TW": "Open Design 著陸簡報套件",
    "ja": "Open Design ランディングデッキ",
    "ko": "Open Design 랜딩 덱",
    "de": "Open Design Landing Deck",
    "fr": "Open Design Landing Deck",
    "ru": "Open Design Landing Deck",
    "es": "Open Design Landing Deck",
    "pt-BR": "Open Design Landing Deck",
    "it": "Open Design Landing Deck",
    "vi": "Open Design Landing Deck",
    "pl": "Open Design Landing Deck",
